Lemma exec_fari_d : forall sz op rd rs1 rs2 rm c md,
  rmode_of_field (bv_unsigned rm) (frm_of c) = Some md ->
  exec sz (Fari op FMT_D rd rs1 rs2 rm) c =
  EDone (fset rd (fari_d op md (fget c rs1) (fget c rs2))
